/*
 * NeolyxOS Kernel - Boot Splash Screen
 *
 * Logo-centred boot screen: the NeolyxOS logo, a thin progress bar under
 * it and an optional one-line caption in NXSans. Everything is drawn
 * straight into the boot framebuffer before the userspace desktop takes
 * it over, so this file holds no GUI toolkit code, only pixel blits.
 *
 * Assets (logo palette image and the NXSans glyph atlas) are generated by
 * tools/gen_boot_splash.py into splash_assets.h; about 21 KB of rodata.
 *
 * Every entry point is a no-op until splash_init() has accepted a valid
 * framebuffer, and splash_update() is a no-op unless the splash is the
 * thing on screen (splash_show() called, splash_hide() not), so boot
 * paths that never showed the splash can call it safely.
 *
 * Copyright (c) 2025-2026 KetiveeAI
 */

#include <stdint.h>
#include "splash_assets.h"

extern void serial_puts(const char *s);

/* Colors (0x00RRGGBB). SPLASH_BG must match BG_RGB in gen_boot_splash.py,
 * because the logo is pre-composited onto it. */
#define SPLASH_BG          0x000B0B12
#define SPLASH_TRACK       0x002A2A36
#define SPLASH_FILL        0x00E6E4F2
#define SPLASH_CAPTION     0x007A7A8C

/* Layout at 1x; everything is multiplied by splash_scale */
#define SPLASH_LOGO_RAISE  24    /* logo centre sits this far above screen centre */
#define SPLASH_BAR_GAP     56    /* logo bottom to bar top */
#define SPLASH_BAR_W       200
#define SPLASH_BAR_H       5
#define SPLASH_CAPTION_GAP 26    /* bar bottom to caption line top */
#define SPLASH_CAPTION_MAX 420   /* widest caption, in px */

/* Bound on framebuffer size we accept (16K x 16K) */
#define SPLASH_MAX_DIM     16384

/* State */
static volatile uint32_t *splash_fb = 0;
static uint32_t splash_width = 0;
static uint32_t splash_height = 0;
static uint32_t splash_stride = 0;     /* in pixels */
static uint32_t splash_scale = 1;
static int splash_active = 0;
static uint32_t current_progress = 0;

/* Computed layout */
static uint32_t bar_x, bar_y, bar_w, bar_h;
static uint32_t caption_y, caption_h, caption_box_w;

/* ============ Pixel helpers ============ */

static inline void splash_put_pixel(uint32_t x, uint32_t y, uint32_t color) {
    if (x < splash_width && y < splash_height) {
        splash_fb[(uint64_t)y * splash_stride + x] = color;
    }
}

static void splash_fill_rect(uint32_t x, uint32_t y, uint32_t w, uint32_t h, uint32_t color) {
    if (x >= splash_width || y >= splash_height) return;
    if (w > splash_width - x) w = splash_width - x;
    if (h > splash_height - y) h = splash_height - y;
    for (uint32_t j = 0; j < h; j++) {
        volatile uint32_t *row = splash_fb + (uint64_t)(y + j) * splash_stride + x;
        for (uint32_t i = 0; i < w; i++) {
            row[i] = color;
        }
    }
}

/* Blend fg over bg with alpha 0..255 */
static inline uint32_t splash_blend(uint32_t fg, uint32_t bg, uint32_t a) {
    uint32_t ia = 255 - a;
    uint32_t r = (((fg >> 16) & 0xFF) * a + ((bg >> 16) & 0xFF) * ia + 127) / 255;
    uint32_t g = (((fg >> 8) & 0xFF) * a + ((bg >> 8) & 0xFF) * ia + 127) / 255;
    uint32_t b = ((fg & 0xFF) * a + (bg & 0xFF) * ia + 127) / 255;
    return (r << 16) | (g << 8) | b;
}

/* ============ Logo ============ */

static void splash_draw_logo(uint32_t x0, uint32_t y0) {
    uint32_t s = splash_scale;
    for (uint32_t y = 0; y < SPLASH_LOGO_H; y++) {
        const uint8_t *src = &splash_logo_pixels[y * SPLASH_LOGO_W];
        for (uint32_t x = 0; x < SPLASH_LOGO_W; x++) {
            uint32_t color = splash_logo_palette[src[x]];   /* 256 entries */
            for (uint32_t dy = 0; dy < s; dy++) {
                for (uint32_t dx = 0; dx < s; dx++) {
                    splash_put_pixel(x0 + x * s + dx, y0 + y * s + dy, color);
                }
            }
        }
    }
}

/* ============ Progress bar ============ */

/*
 * Coverage (0..16) of the pixel (px, py) by a horizontal capsule that
 * spans [x0, x1) x [y0, y0 + h). 4x4 supersampling in 1/8 px units.
 */
static uint32_t splash_capsule_cov(uint32_t px, uint32_t py,
                                   uint32_t x0, uint32_t x1, uint32_t y0, uint32_t h) {
    int64_t r = (int64_t)h * 4;                 /* radius, 1/8 px */
    int64_t cy = (int64_t)y0 * 8 + r;
    int64_t cx_min = (int64_t)x0 * 8 + r;
    int64_t cx_max = (int64_t)x1 * 8 - r;
    if (cx_max < cx_min) cx_max = cx_min;
    uint32_t cov = 0;
    for (int sy = 0; sy < 4; sy++) {
        int64_t y = (int64_t)py * 8 + sy * 2 + 1;
        int64_t dy = y - cy;
        for (int sx = 0; sx < 4; sx++) {
            int64_t x = (int64_t)px * 8 + sx * 2 + 1;
            int64_t cx = x < cx_min ? cx_min : (x > cx_max ? cx_max : x);
            int64_t dx = x - cx;
            if (dx * dx + dy * dy <= r * r) cov++;
        }
    }
    return cov;
}

static void splash_draw_bar(uint32_t percent) {
    uint32_t fill_w = (bar_w * percent) / 100;
    if (percent > 0 && fill_w < bar_h) fill_w = bar_h;   /* show a round dot at least */
    uint32_t fill_x1 = bar_x + fill_w;

    for (uint32_t py = bar_y; py < bar_y + bar_h; py++) {
        for (uint32_t px = bar_x; px < bar_x + bar_w; px++) {
            uint32_t c = SPLASH_BG;
            uint32_t t = splash_capsule_cov(px, py, bar_x, bar_x + bar_w, bar_y, bar_h);
            if (t) c = splash_blend(SPLASH_TRACK, c, t * 255 / 16);
            if (percent > 0 && px < fill_x1) {
                uint32_t f = splash_capsule_cov(px, py, bar_x, fill_x1, bar_y, bar_h);
                if (f) c = splash_blend(SPLASH_FILL, c, f * 255 / 16);
            }
            splash_put_pixel(px, py, c);
        }
    }
}

/* ============ Caption text (NXSans glyph atlas) ============ */

static const splash_glyph_t *splash_glyph(char ch) {
    unsigned char c = (unsigned char)ch;
    if (c < SPLASH_FONT_FIRST || c > SPLASH_FONT_LAST) c = '?';
    return &splash_font_glyphs[c - SPLASH_FONT_FIRST];
}

/* Width in px (1x) of text, stopping before it would exceed max_w */
static uint32_t splash_text_width(const char *text, uint32_t max_w, uint32_t *out_len) {
    uint32_t pen64 = 0, len = 0;
    while (text[len]) {
        uint32_t next = pen64 + splash_glyph(text[len])->adv64;
        if ((next + 63) / 64 > max_w) break;
        pen64 = next;
        len++;
    }
    if (out_len) *out_len = len;
    return (pen64 + 63) / 64;
}

static void splash_draw_text(uint32_t x0, uint32_t y0, const char *text, uint32_t len, uint32_t color) {
    uint32_t s = splash_scale;
    uint32_t pen64 = 0;
    for (uint32_t n = 0; n < len; n++) {
        const splash_glyph_t *g = splash_glyph(text[n]);
        int32_t gx = (int32_t)x0 + (int32_t)(((pen64 + 32) / 64) * s) + g->x * (int32_t)s;
        int32_t gy = (int32_t)y0 + g->y * (int32_t)s;
        const uint8_t *src = &splash_font_data[g->offset];
        for (uint32_t y = 0; y < g->h; y++) {
            for (uint32_t x = 0; x < g->w; x++) {
                uint32_t a = src[y * g->w + x];
                if (!a) continue;
                uint32_t c = splash_blend(color, SPLASH_BG, a);
                for (uint32_t dy = 0; dy < s; dy++) {
                    for (uint32_t dx = 0; dx < s; dx++) {
                        int32_t px = gx + (int32_t)(x * s + dx);
                        int32_t py = gy + (int32_t)(y * s + dy);
                        if (px >= 0 && py >= 0) splash_put_pixel((uint32_t)px, (uint32_t)py, c);
                    }
                }
            }
        }
        pen64 += g->adv64;
    }
}

static void splash_draw_caption(const char *text) {
    uint32_t box_x = splash_width > caption_box_w ? (splash_width - caption_box_w) / 2 : 0;
    splash_fill_rect(box_x, caption_y, caption_box_w, caption_h, SPLASH_BG);
    if (!text || !text[0]) return;

    uint32_t len = 0;
    uint32_t w = splash_text_width(text, SPLASH_CAPTION_MAX, &len) * splash_scale;
    uint32_t x = splash_width > w ? (splash_width - w) / 2 : 0;
    splash_draw_text(x, caption_y, text, len, SPLASH_CAPTION);
}

/* ============ Public API ============ */

/*
 * splash_init - attach the splash to a linear 32bpp framebuffer.
 * Rejects a null address, zero or absurd sizes and a pitch that cannot
 * hold a row; on rejection the splash stays disabled.
 */
void splash_init(uint64_t fb_addr, uint32_t width, uint32_t height, uint32_t pitch) {
    splash_fb = 0;
    splash_active = 0;
    current_progress = 0;

    if (!fb_addr || width == 0 || height == 0 ||
        width > SPLASH_MAX_DIM || height > SPLASH_MAX_DIM ||
        (pitch & 3) != 0 || pitch / 4 < width) {
        serial_puts("[SPLASH] Invalid framebuffer, splash disabled\n");
        return;
    }

    splash_width = width;
    splash_height = height;
    splash_stride = pitch / 4;
    splash_scale = (height >= 1440 && width >= 2400) ? 2 : 1;

    uint32_t s = splash_scale;
    uint32_t logo_h = SPLASH_LOGO_H * s;
    bar_w = SPLASH_BAR_W * s;
    bar_h = SPLASH_BAR_H * s;
    caption_h = (SPLASH_FONT_ASCENT + SPLASH_FONT_DESCENT) * s;
    caption_box_w = SPLASH_CAPTION_MAX * s;
    if (caption_box_w > width) caption_box_w = width;

    /* Everything must fit vertically; otherwise the panel is too small */
    uint32_t block_h = logo_h + SPLASH_BAR_GAP * s + bar_h + SPLASH_CAPTION_GAP * s + caption_h;
    if (bar_w > width || block_h + 2 * SPLASH_LOGO_RAISE * s > height) {
        serial_puts("[SPLASH] Framebuffer too small, splash disabled\n");
        return;
    }

    uint32_t logo_y = height / 2 - SPLASH_LOGO_RAISE * s - logo_h / 2;
    bar_x = (width - bar_w) / 2;
    bar_y = logo_y + logo_h + SPLASH_BAR_GAP * s;
    caption_y = bar_y + bar_h + SPLASH_CAPTION_GAP * s;

    splash_fb = (volatile uint32_t *)fb_addr;
    serial_puts("[SPLASH] Initialized\n");
}

/* splash_show - clear the screen and draw logo plus an empty bar */
void splash_show(void) {
    if (!splash_fb) return;

    uint32_t s = splash_scale;
    uint32_t logo_w = SPLASH_LOGO_W * s;
    uint32_t logo_h = SPLASH_LOGO_H * s;

    splash_fill_rect(0, 0, splash_width, splash_height, SPLASH_BG);
    splash_draw_logo((splash_width - logo_w) / 2,
                     splash_height / 2 - SPLASH_LOGO_RAISE * s - logo_h / 2);
    current_progress = 0;
    splash_draw_bar(0);
    splash_active = 1;
}

/*
 * splash_update - set the progress bar (clamped to 0..100) and caption.
 * status == NULL keeps the current caption, "" clears it.
 */
void splash_update(uint32_t percent, const char *status) {
    if (!splash_fb || !splash_active) return;

    if (percent > 100) percent = 100;
    if (percent != current_progress) {
        current_progress = percent;
        splash_draw_bar(percent);
    }
    if (status) {
        splash_draw_caption(status);
    }
}

/* splash_hide - stop drawing; whoever owns the screen next repaints it */
void splash_hide(void) {
    if (!splash_fb) return;
    splash_active = 0;
    splash_fill_rect(0, 0, splash_width, splash_height, SPLASH_BG);
}

uint32_t splash_get_progress(void) {
    return current_progress;
}
